    def self.numbers_are_never_reused
      Spec::Testing.gives(-> { Todo::Board.add("a") }) { 1 }
      Spec::Testing.gives(-> { Todo::Board.add("b") }) { 2 }
      Todo::Board.remove(2)
      Spec::Testing.gives(-> { Todo::Board.add("c") }) { 3 }
    end
    SUITE.test("todo.tests.scenarios.numbers_are_never_reused", method(:numbers_are_never_reused))

