    # test done_and_reopen_move_once (todo/tests/scenarios.slg:39)
    def self.done_and_reopen_move_once
      Todo::Board.done(2)
      Spec::Testing.fails("AlreadyDone", -> { Todo::Board.done(2) })
      Todo::Board.reopen(2)
      Spec::Testing.fails("NotDone", -> { Todo::Board.reopen(2) })
      Spec.assert(Spec.effect("cli.out", :text) == "2 [x] plain\n2 [ ] plain\n")
    end
    SUITE.test(
      "todo.tests.scenarios.done_and_reopen_move_once",
